float rand(float t)
{
    return fract(sin(t) * 432231.9);
}

float noise_1d(float t)
{
    float i = floor(t);
    float f = fract(t);
    return mix(rand(i), rand(i + 1.0), smoothstep(0.0, 1.0, f));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{

    //Normalized screen space Coordinates
    vec2 uv = fragCoord / iResolution.xy;

    vec3 color;

    float y = noise_1d(noise_1d(uv.x * 400.0 + iTime));

    color = uv.y < y ? mix(vec3(0.0, 1.0, 0.0), vec3(1.0, 0.0, 0.0),uv.y+0.5) : vec3(0.0);
    fragColor = vec4(color, 1.0f);
}
